{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "example-email-marketing",
  "title": "Email Marketing",
  "title_i18n": {
    "zh-CN": "电子邮件营销",
    "zh-TW": "電子郵件行銷",
    "ja": "メールマーケティング",
    "ko": "이메일 마케팅",
    "de": "E-Mail-Marketing",
    "fr": "Marketing par e-mail",
    "ru": "Email-маркетинг",
    "es": "Marketing por correo electrónico",
    "pt-BR": "Marketing por e-mail",
    "it": "Email marketing",
    "vi": "Tiếp thị qua email",
    "pl": "Email marketing",
    "id": "Email Marketing",
    "nl": "E-mailmarketing",
    "ar": "التسويق عبر البريد الإلكتروني",
    "tr": "E-posta Pazarlama",
    "uk": "Email-маркетинг",
    "en": "Email Marketing"
  },
  "version": "0.1.0",
  "description": "A brand product-launch email — masthead with wordmark, hero image block,\nheadline lockup with skewed-italic accent, body copy, primary CTA, and a\nspecifications grid. Pure HTML email layout (centered single column, table\nfallback). Use when the brief asks for an \"email\", \"newsletter blast\",\n\"MJML\", \"product launch email\", or \"email template\".",
  "description_i18n": {
    "zh-CN": "品牌产品发布电子邮件模板，包含报头、主图、斜体强调标题、正文、主要行动号召按钮和规格表格，采用HTML居中单栏布局。",
    "zh-TW": "品牌產品發布電子郵件範本，包含報頭、主圖、斜體強調標題、正文、主要行動呼籲按鈕和規格表格，採用HTML置中單欄佈局。",
    "ja": "ブランド製品発売用メールテンプレート。マストヘッド、ヒーロー画像、斜体アクセント見出し、本文、CTAボタン、仕様グリッドを含むHTML中央寄せ単一カラムレイアウト。",
    "ko": "브랜드 제품 출시 이메일 템플릿. 마스트헤드, 히어로 이미지, 기울임체 강조 헤드라인, 본문, CTA 버튼, 사양 그리드를 포함한 HTML 중앙 정렬 단일 컬럼 레이아웃.",
    "de": "E-Mail-Vorlage für Produkteinführungen mit Masthead, Hero-Bild, kursiver Überschrift, Fließtext, primärem CTA und Spezifikationstabelle im zentrierten HTML-Einspaltenlayout.",
    "fr": "Modèle d'e-mail de lancement produit avec en-tête, image hero, titre en italique, texte principal, CTA principal et grille de spécifications en mise en page HTML centrée sur une colonne.",
    "ru": "Шаблон email для запуска продукта с шапкой, главным изображением, заголовком курсивом, основным текстом, CTA-кнопкой и таблицей характеристик в одноколоночной HTML-верстке.",
    "es": "Plantilla de correo para lanzamiento de producto con cabecera, imagen hero, titular en cursiva, texto principal, CTA principal y cuadrícula de especificaciones en diseño HTML de columna única centrada.",
    "pt-BR": "Template de e-mail para lançamento de produto com cabeçalho, imagem hero, título em itálico, corpo de texto, CTA principal e grade de especificações em layout HTML de coluna única centralizada.",
    "it": "Template email per lancio prodotto con testata, immagine hero, titolo in corsivo, testo principale, CTA primario e griglia specifiche in layout HTML a colonna singola centrata.",
    "vi": "Mẫu email ra mắt sản phẩm với đầu trang, hình ảnh chính, tiêu đề nghiêng, nội dung chính, nút CTA chính và bảng thông số kỹ thuật trong bố cục HTML một cột căn giữa.",
    "pl": "Szablon emaila do premiery produktu z nagłówkiem, obrazem hero, nagłówkiem kursywą, treścią główną, przyciskiem CTA i tabelą specyfikacji w wyśrodkowanym jednoszpaltowym układzie HTML.",
    "id": "Template email peluncuran produk dengan masthead, gambar hero, judul miring, teks utama, tombol CTA utama, dan grid spesifikasi dalam tata letak HTML kolom tunggal terpusat.",
    "nl": "E-mailtemplate voor productlancering met masthead, hero-afbeelding, cursieve kop, hoofdtekst, primaire CTA en specificatieraster in gecentreerde HTML-layout met enkele kolom.",
    "ar": "قالب بريد إلكتروني لإطلاق المنتج مع رأس الصفحة، صورة رئيسية، عنوان مائل، نص أساسي، زر CTA رئيسي، وجدول مواصفات في تخطيط HTML بعمود واحد في المنتصف.",
    "tr": "Ürün lansmanı için e-posta şablonu: başlık, ana görsel, eğik vurgulu başlık, ana metin, birincil CTA butonu ve özellik tablosu içeren ortalanmış tek sütunlu HTML düzeni.",
    "uk": "Шаблон email для запуску продукту з шапкою, головним зображенням, заголовком курсивом, основним текстом, CTA-кнопкою та таблицею характеристик в одноколонковій HTML-версії.",
    "en": "A brand product-launch email — masthead with wordmark, hero image block,\nheadline lockup with skewed-italic accent, body copy, primary CTA, and a\nspecifications grid. Pure HTML email layout (centered single column, table\nfallback). Use when the brief asks for an \"email\", \"newsletter blast\",\n\"MJML\", \"product launch email\", or \"email template\"."
  },
  "license": "MIT",
  "author": {
    "name": "Open Design",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/examples/email-marketing",
  "tags": [
    "example",
    "first-party",
    "prototype",
    "marketing",
    "web",
    "desktop",
    "email",
    "email-template",
    "newsletter",
    "email-blast",
    "product-launch-email",
    "mjml",
    "untitled"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "prototype",
    "platform": "desktop",
    "scenario": "marketing",
    "surface": "web",
    "preview": {
      "type": "html",
      "entry": "./example.html"
    },
    "useCase": {
      "query": {
        "en": "Design a launch email for a sporty running shoe brand — masthead, hero, big headline lockup, specs grid, CTA.",
        "zh-CN": "使用这个插件完成以下任务：Design a launch email for a sporty running shoe brand — masthead, hero, big headline lockup, specs grid, CTA."
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Email Marketing"
        }
      ]
    },
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "designSystem": {
        "primary": true
      },
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ]
  }
}
